WITH zhztgx AS ( select b.bookset_id,/** 账套代码**/ /** 数据字典：收益类型.预期收益 02 **/ case when c.channel_id is null then case when b.acct_mode = '02' then b.acct_subject_id else nvl(d.portfolio_id,b.acct_subject_id) end else case when e.acct_mode='02' then e.acct_subject_id else nvl(f.portfolio_id,e.acct_subject_id) end end portfolio_id, /** 组合代码**/ c.channel_id/** 通道代码**/ from bok_bookset b /** 账套表**/ left join bok_bookset_re c on b.bookset_id = c.bookset_id_son /** 母子账套关系**/ left join fin_product_add d on b.acct_subject_id = d.finprod_id /** 标的类金融产品附属表**/ left join bok_bookset e on c.bookset_id = e.bookset_id /** 账套表**/ left join fin_product_add f on e.acct_subject_id = f.finprod_id /** 标的类金融产品附属表**/ ) SELECT * FROM ( SELECT BOK_BOOKSET.BOOKSET_ID bookSetId, /** 账套代码 **/ BOK_BOOKSET.BOOKSET_NAME bookSetName, /** 账套名称 **/ A.INV_AIM invAim, /** 投资目的 **/ nvl(A.TDY_COST_AMT,0) + nvl(bjysk.RECE_AMT,0) bookValue, /** 账面价值 **/ nvl(A.TDY_INTINCEXP,0) + nvl(lxysk.RECE_AMT,0) + nvl(lxysk.PENALTY_INT_AMT,0) + nvl(bjysk.PENALTY_INT_AMT,0) interestReceivable, /** 应收利息 **/ nvl(A.TDY_COST_AMT,0) + nvl(A.TDY_INTINCEXP,0) + nvl(bjysk.RECE_AMT,0) + nvl(lxysk.RECE_AMT,0) + nvl(lxysk.PENALTY_INT_AMT,0) + nvl(bjysk.PENALTY_INT_AMT,0) eadDefaultExposure, /** EAD违约风险暴露 **/ ROW_NUMBER() OVER(PARTITION BY A.BOOKSET_ID,A.BOK_DETAIL_ID ORDER BY A.BOOK_SUMMARY_ORDER DESC) AS rn FROM BOK_STAT_DET_POSIITON A /** 统计分析明细表（账务明细） **/ LEFT JOIN BOK_BOOKSET /** 账套 **/ ON A.BOOKSET_ID = BOK_BOOKSET.BOOKSET_ID LEFT JOIN BOK_DETAIL_ID /** 账务明细代码表 **/ ON A.BOOKSET_ID = BOK_DETAIL_ID.BOOKSET_ID AND A.BOK_DETAIL_ID = BOK_DETAIL_ID.BOK_DETAIL_ID left join zhztgx on BOK_BOOKSET.BOOKSET_ID = zhztgx.bookset_id left join ( select PTL_SEC_RECEIVABLES.Portfolio_Id, /** 组合代码 **/ PTL_SEC_RECEIVABLES.Cdate, /** 日期 **/ PTL_SEC_RECEIVABLES.Inv_Aim, /** 投资目的 **/ PTL_SEC_RECEIVABLES.SEC_ACCT_ID, /** 证券管理账户/通道代码 **/ PTL_SEC_RECEIVABLES.RECE_AMT, /** 应收款 **/ PTL_SEC_RECEIVABLES.PENALTY_INT_AMT, /** 罚息金额 **/ PTL_SEC_RECEIVABLES.Finprod_Id /** 金融产品代码 **/ from PTL_SEC_RECEIVABLES /** 组合资产应收款 **/ left join FIN_TRADE_PRODUCT /** 交易类金融产品 **/ on PTL_SEC_RECEIVABLES.Finprod_Id = FIN_TRADE_PRODUCT.Finprod_Id and PTL_SEC_RECEIVABLES.BRANCH = FIN_TRADE_PRODUCT.Branch where FIN_TRADE_PRODUCT.BRANCH_TYPE = 'D01' ) bjysk /** 本金应收款 **/ ON bjysk.Portfolio_Id = zhztgx.portfolio_id AND bjysk.Cdate = A.BOOK_DATE AND A.INV_AIM = bjysk.Inv_Aim AND nvl(zhztgx.channel_id,'999999') = nvl(bjysk.SEC_ACCT_ID,'') AND bjysk.Finprod_Id = BOK_DETAIL_ID.BUSI_ID left join ( select PTL_SEC_RECEIVABLES.Portfolio_Id, /** 组合代码 **/ PTL_SEC_RECEIVABLES.Cdate, /** 日期 **/ PTL_SEC_RECEIVABLES.Inv_Aim, /** 投资目的 **/ PTL_SEC_RECEIVABLES.SEC_ACCT_ID, /** 证券管理账户/通道代码 **/ PTL_SEC_RECEIVABLES.RECE_AMT, /** 应收款 **/ PTL_SEC_RECEIVABLES.PENALTY_INT_AMT, /** 罚息金额 **/ PTL_SEC_RECEIVABLES.Finprod_Id /** 金融产品代码 **/ from PTL_SEC_RECEIVABLES /** 组合资产应收款 **/ left join FIN_TRADE_PRODUCT /** 交易类金融产品 **/ on PTL_SEC_RECEIVABLES.Finprod_Id = FIN_TRADE_PRODUCT.Finprod_Id and PTL_SEC_RECEIVABLES.BRANCH = FIN_TRADE_PRODUCT.Branch where FIN_TRADE_PRODUCT.BRANCH_TYPE = 'D02' )lxysk /** 利息应收款 **/ ON lxysk.Portfolio_Id = zhztgx.portfolio_id AND lxysk.Cdate = A.BOOK_DATE AND A.INV_AIM = lxysk.Inv_Aim AND nvl(zhztgx.channel_id,'999999') = nvl(lxysk.SEC_ACCT_ID,'') AND lxysk.Finprod_Id = BOK_DETAIL_ID.BUSI_ID WHERE 1 = 1
and BOK_DETAIL_ID.BUSI_ID = #{finprodId}
and A.BOOK_DATE < to_date(#{valDate},'yyyy-MM-dd')
) B WHERE B.rn =1

select TRD_ASSET_LOSS.VAL_DATE valDate, TRD_ASSET_LOSS.SEC_ID finprodId, TRD_ASSET_LOSS.LOSS_TEST_TYPE lossTestType from TRD_ASSET_LOSS where TRD_ASSET_LOSS.Status = #{status_init_01} and trd_asset_loss.val_date = to_date(#{valDate},'yyyy-MM-dd') and trd_asset_loss.SEC_ID = #{finprodId,jdbcType=VARCHAR}
and trd_asset_loss.PEROID = #{peroid,jdbcType=DECIMAL}
AND TRD_ASSET_LOSS.STR_DATE <= to_date(#{strDate},'yyyy-MM-dd') AND TRD_ASSET_LOSS.END_DATE >= to_date(#{strDate},'yyyy-MM-dd')
AND TRD_ASSET_LOSS.STR_DATE <= to_date(#{endDate},'yyyy-MM-dd') AND TRD_ASSET_LOSS.END_DATE >= to_date(#{endDate},'yyyy-MM-dd')

select TRD_ASSET_LOSS.VAL_DATE valDate, TRD_ASSET_LOSS.SEC_ID finprodId, TRD_ASSET_LOSS.LOSS_TEST_TYPE lossTestType from TRD_ASSET_LOSS where TRD_ASSET_LOSS.Status = #{status_init_01} and trd_asset_loss.val_date = to_date(#{valDate},'yyyy-MM-dd') and trd_asset_loss.SEC_ID = #{finprodId,jdbcType=VARCHAR}
and trd_asset_loss.PEROID = #{peroid,jdbcType=DECIMAL}
AND TRD_ASSET_LOSS.STR_DATE >= to_date(#{strDate},'yyyy-MM-dd') AND TRD_ASSET_LOSS.END_DATE <= to_date(#{endDate},'yyyy-MM-dd')
